  "required sections. This measures whether the note is filled in, not whether it is clinically sufficient — and it is not a billing indicator.": "आवश्यक अनुभाग। यह टिप्पणी भरी है या नहीं मापता है, नैदानिक पर्याप्तता नहीं; यह बिलिंग संकेतक भी नहीं है।",
  "rows": "पंक्तियाँ",
  "sections, ordered core → type → specialty → complaint → context. Each names its layer.": "अनुभाग: मूल → प्रकार → विशेषज्ञता → शिकायत → संदर्भ। प्रत्येक अपनी परत बताता है।",
