  "template.clinical.guideLimits": "डेमो देखभाल डेटा काल्पनिक है। वास्तविक नैदानिक निर्णय, पात्रता, फ़ाइल भंडारण और सूचनाओं के लिए अधिकृत सेवाएँ चाहिए। असहेजे मान मेमोरी में रहते हैं; संवेदनशील ड्राफ़्ट स्वतः नहीं सहेजे जाते।",
